from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The longest straight non-background run is the motif to stamp.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == background:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != background:
                c += 1
            runs.append((c - start, [grid[r][x] for x in range(start, c)], (r, start), (0, 1)))
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == background:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != background:
                r += 1
            runs.append((r - start, [grid[x][c] for x in range(start, r)], (start, c), (1, 0)))

    _, motif, (mr, mc), (dr, dc) = max(runs, key=lambda item: item[0])
    motif_colors = set(motif)
    marker_colors = {v for row in grid for v in row if v != background and v not in motif_colors}
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] in marker_colors]

    out = [[background] * w for _ in range(h)]
    # Keep the motif where it appeared in the input.
    for i, value in enumerate(motif):
        out[mr + i * dr][mc + i * dc] = value

    # Stamp a copy centered on every isolated marker; clip at grid edges.
    anchor = len(motif) // 2
    for r, c in markers:
        for i, value in enumerate(motif):
            rr, cc = r + (i - anchor) * dr, c + (i - anchor) * dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out

